-- SafetyTraining v20.050b
-- Reconcile live completion-v2 confined-space update, evidence and provenance.
-- Idempotent and UUID-independent.

DO $do$
DECLARE r jsonb; v_lu uuid; v_luv uuid; v_course uuid; v_cv uuid; v_module uuid;
BEGIN
  FOR r IN SELECT value FROM jsonb_array_elements($units$
  [
    {"key":"update:confined:recognition","title":"Riconoscimento, permesso di lavoro e condizioni di ingresso","summary":"Rivalutare prima di ogni accesso se ambiente, lavoro, energie e ruoli corrispondono allo scenario pianificato.","case":"Un serbatoio dichiarato vuoto è ancora collegato a una linea di processo: individuare isolamenti, verifiche e condizione che impedisce l’ingresso.","detail":"Un ambiente sospetto di inquinamento o confinato non diventa sicuro per abitudine o per un singolo controllo. Prima dell’ingresso si identificano ambiente, attività, sostanze ed energie, collegamenti con impianti, persone coinvolte, comunicazioni e criteri di sospensione. Il permesso/procedura deve descrivere la situazione reale, non essere una formalità precompilata.","procedure":["confermare ambiente e attività effettiva","verificare ruoli, autorizzazioni e comunicazione","isolare fonti di energia e materia secondo procedura","controllare disponibilità di misure, strumenti, DPI e recupero","non autorizzare ingresso se una condizione essenziale non è verificata"],"errors":["riusare un permesso precedente senza rivalutazione","entrare per “dare solo un’occhiata”","confondere apertura del passo d’uomo con ventilazione sufficiente","iniziare senza un piano di emergenza praticabile"]},
    {"key":"update:confined:atmosphere","title":"Atmosfera, monitoraggio, ventilazione e isolamento","summary":"Applicare la logica di misura e controllo dell’atmosfera senza affidarsi ai sensi.","case":"Il rilevatore entra in allarme durante il lavoro: uscita secondo procedura, blocco di nuovi ingressi e rivalutazione di fonte, ventilazione e misure prima di ogni ripresa.","detail":"Ossigeno insufficiente o eccessivo, gas/vapori tossici e atmosfere infiammabili possono non essere percepibili. Il monitoraggio usa strumenti adatti, controllati e impiegati secondo procedura, con punti e tempi coerenti con geometria e sostanze. La ventilazione può ridurre il rischio ma non sostituisce l’isolamento delle fonti.","procedure":["verificare strumento e configurazione secondo istruzioni","misurare prima dell’ingresso e durante quando previsto","considerare stratificazione e punti non rappresentativi","mantenere ventilazione e isolamento per il tempo necessario","interrompere se valori o allarmi escono dai limiti della procedura"],"errors":["fidarsi dell’odore","misurare una sola volta all’ingresso","spegnere un allarme senza comprenderne la causa","usare ventilazione non prevista dalla valutazione"]},
    {"key":"update:confined:dpi-comms","title":"DPI, APVR, comunicazione e sorveglianza","summary":"Ripassare uso e limiti dei DPI/APVR e il ruolo operativo dell’assistente esterno.","case":"Durante l’accesso la comunicazione si interrompe: spiegare perché è una condizione di stop e come si attiva la procedura.","detail":"DPI anticaduta, recupero e protezione respiratoria richiedono scelta coerente, addestramento sul modello usato e controlli pre-uso. L’assistente esterno mantiene comunicazione, osserva le condizioni e attiva l’emergenza; non abbandona la funzione per entrare impulsivamente.","procedure":["controllare compatibilità e integrità dei DPI previsti","indossare e regolare i dispositivi secondo addestramento","provare la comunicazione prima dell’ingresso","mantenere conteggio e contatto con gli operatori","attivare l’emergenza senza ingresso improvvisato dell’assistente"],"errors":["scegliere APVR senza valutazione specifica","usare modelli diversi senza addestramento coerente","perdere la comunicazione e continuare","trasformare l’assistente in soccorritore improvvisato"]},
    {"key":"update:confined:rescue","title":"Emergenza, recupero e simulazione integrata","summary":"Evitare il soccorso impulsivo e verificare che il piano di recupero sia realmente eseguibile.","case":"Operatore non risponde all’interno: l’assistente attiva allarme e piano, mantiene il controllo dell’area e usa solo sistemi per cui l’organizzazione è preparata.","detail":"Molti eventi multipli negli spazi confinati nascono dal tentativo spontaneo di soccorso. Il piano stabilisce chi allerta, chi mantiene il controllo esterno, quali sistemi di recupero possono essere usati, quando serve una squadra specialistica e come evitare che un secondo soccorritore diventi vittima.","procedure":["riconoscere l’emergenza e sospendere ogni nuovo ingresso","allertare risorse interne ed esterne previste","usare sistemi di recupero dall’esterno quando previsti e addestrati","impedire ingressi spontanei non protetti","riesaminare evento e barriere prima di riaprire il lavoro"],"errors":["entrare d’impulso per aiutare","avere sistemi di recupero senza averne verificato configurazione e uso","pianificare il recupero solo dopo l’emergenza","simulare creando una vera esposizione"]}
  ]::jsonb) LOOP
    INSERT INTO public.learning_units(stable_key,title,summary,default_minutes,source_group,tags,active,metadata)
    VALUES(r->>'key',r->>'title',r->>'summary',60,'SafetyTraining completion-v2',array['safetytraining','confined-space','update','completion-v2'],true,
      jsonb_build_object('source_audit',jsonb_build_object('status','reviewed','checked_on','2026-10-15','reuse_policy','facts_and_original_didactic_rewrite','primary_evidence','INAIL Infor.MO Scheda 11'),'learner_ready',true,'teacher_ready',true,'practical_focus',true,'didactic_version','completion-v2'))
    ON CONFLICT(stable_key) DO UPDATE SET title=excluded.title,summary=excluded.summary,default_minutes=60,source_group=excluded.source_group,tags=excluded.tags,active=true,metadata=excluded.metadata,updated_at=now() RETURNING id INTO v_lu;

    INSERT INTO public.learning_unit_versions(learning_unit_id,version_number,status,content,published_at)
    VALUES(v_lu,1,'draft',jsonb_build_object(
      'case',r->>'case','norm','D.Lgs. 81/2008 artt. 66, 77, 121 e Allegato IV punto 3; D.P.R. 177/2011; Accordo Stato-Regioni 17/04/2025.',
      'quiz',jsonb_build_object('options',jsonb_build_array('Si continua velocemente','Si interrompe secondo procedura e si ripristina una condizione controllata','Si manda dentro l’assistente','Si ignora se nessuno avverte sintomi'),'question','Se la comunicazione o il monitoraggio richiesti vengono meno durante l’ingresso, cosa si fa?','explanation','Comunicazione e monitoraggio sono barriere essenziali: se vengono meno, il lavoro non corrisponde più allo scenario autorizzato.','correct_index',1),
      'title',r->>'title','detail',r->>'detail','minutes',60,'quality',jsonb_build_object('learner_ready',true,'teacher_ready',true,'scenario_based',true,'practical_focus',true),'summary',r->>'summary',
      'visuals',jsonb_build_array('procedura-operativa-5-fasi.svg','stop-segnala-ripristina.svg','modello-farfalla-rischio.svg'),'procedure',r->'procedure',
      'case_method',jsonb_build_object('sequence',jsonb_build_array('riconoscere l’ambiente e i pericoli','verificare isolamento e condizioni di ingresso','misurare e controllare l’atmosfera secondo procedura','mantenere comunicazione e sorveglianza','in emergenza attivare il piano senza ingresso impulsivo'),'teacher_prompt','Far individuare al gruppo il primo punto in cui la catena dell’evento poteva essere interrotta e quale barriera tecnica, organizzativa o procedurale mancava.'),
      'common_errors',r->'errors','delivery_note','Il materiale è integralmente consultabile; l’aggiornamento pratico/addestrativo richiesto non è sostituito dalla consultazione digitale.',
      'guided_activity',jsonb_build_array('briefing e permesso simulato','controllo strumenti/DPI','scenario con allarme o perdita comunicazione','attivazione del piano di emergenza e debriefing'),'didactic_version','completion-v2',
      'evidence_sources',jsonb_build_array(jsonb_build_object('url','https://www.inail.it/content/dam/inail-hub-site/documenti/2017/06/Scheda11-InforMO.pdf','use','incident_evidence_and_prevention','title','Gli ambienti confinati - Scheda 11','authority','INAIL - Sistema Infor.MO','checked_on','2026-10-15')),
      'final_assessment',false,'teacher_expansion','Usare procedure, rilevatore e DPI/APVR coerenti con il contesto. Simulare ingresso ed emergenza senza esposizioni reali. Ogni corsista verbalizza criteri GO/NO-GO, segnale di evacuazione e ruolo dell’assistente esterno.'),null)
    ON CONFLICT(learning_unit_id,version_number) DO UPDATE SET status='draft',content=excluded.content,published_at=null;

    INSERT INTO public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
    VALUES(v_lu,'inail-informo-confinati-11','incident_evidence','Dinamiche reali per riconoscimento dei punti di rottura della catena incidentale e prevenzione del soccorso impulsivo.',date '2026-10-15','{}')
    ON CONFLICT(learning_unit_id,source_key,purpose) DO UPDATE SET relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
    INSERT INTO public.learning_unit_sources(learning_unit_id,source_key,purpose,relevance_note,verified_on,metadata)
    VALUES(v_lu,'piemonte-indicazioni-formazione-2025','compliance_crosscheck','Cross-check operativo delle regole formative successive al recepimento ASR 2025.',date '2026-10-15','{}')
    ON CONFLICT(learning_unit_id,source_key,purpose) DO UPDATE SET relevance_note=excluded.relevance_note,verified_on=excluded.verified_on,metadata=excluded.metadata;
  END LOOP;

  SELECT id INTO v_course FROM public.courses WHERE stable_key='agg_spazi_confinati_4h';
  UPDATE public.courses SET title='Aggiornamento ambienti sospetti di inquinamento o confinati - 4h',family='Rischi specialistici',description='Aggiornamento quinquennale di almeno 4h pratiche per ambienti confinati.',nominal_minutes=240,active=true,
    metadata=metadata||'{"blueprint_key":"confined_spaces_update","duration_source":"regulatory","didactic_version":"completion-v2","material_complete":true,"composition_version":"v20_030","delivery_constraint":"physical_only","requires_admin_review":true,"learner_catalog_hidden":true,"learner_material_complete":true,"teacher_material_complete":true,"practical_component_separate":true,"delivery_rules_are_metadata_only":true}'::jsonb,updated_at=now() WHERE id=v_course;
  SELECT id INTO v_cv FROM public.course_versions WHERE course_id=v_course AND version_number=1;
  UPDATE public.course_versions SET status='draft',effective_from=date '2025-05-24',published_at=null,
    syllabus_snapshot='{"source":"v20_030","blueprint_key":"confined_spaces_update","nominal_minutes":240,"didactic_version":"completion-v2","material_minutes":240,"material_complete":true,"learning_unit_count":4}'::jsonb,
    normative_snapshot='{"reference":"ASR 17/04/2025; DPR 177/2011","publication_gate":"Admin/didactic review + practical validation"}'::jsonb WHERE id=v_cv;
  INSERT INTO public.course_modules(course_version_id,module_key,title,position,nominal_minutes) VALUES(v_cv,'confined-update','Aggiornamento ambienti confinati: controllo ingresso ed emergenza',1,240)
    ON CONFLICT(course_version_id,module_key) DO UPDATE SET title=excluded.title,position=1,nominal_minutes=240 RETURNING id INTO v_module;
  FOR r IN SELECT value FROM jsonb_array_elements('[{"k":"update:confined:recognition","p":1},{"k":"update:confined:atmosphere","p":2},{"k":"update:confined:dpi-comms","p":3},{"k":"update:confined:rescue","p":4}]'::jsonb) LOOP
    SELECT luv.id INTO v_luv FROM public.learning_units lu JOIN public.learning_unit_versions luv ON luv.learning_unit_id=lu.id AND luv.version_number=1 WHERE lu.stable_key=r->>'k';
    INSERT INTO public.course_module_units(module_id,unit_version_id,position,required,min_active_seconds,requires_comprehension,completion_rules)
    VALUES(v_module,v_luv,(r->>'p')::int,true,0,true,'{"material_complete":true,"practical_or_guided":true}'::jsonb)
    ON CONFLICT(module_id,unit_version_id) DO UPDATE SET position=excluded.position,required=true,min_active_seconds=0,requires_comprehension=true,completion_rules=excluded.completion_rules;
  END LOOP;
  INSERT INTO public.course_practical_requirements(course_id,requirement_key,title,nominal_minutes,required,completion_mode,metadata)
  VALUES(v_course,'confined_update_practice','Aggiornamento pratico ambienti confinati',240,true,'external_presence','{"delivery":"physical","regulatory":true,"validation_required":true}'::jsonb)
  ON CONFLICT(course_id,requirement_key) DO UPDATE SET title=excluded.title,nominal_minutes=240,required=true,completion_mode=excluded.completion_mode,metadata=excluded.metadata,updated_at=now();
  INSERT INTO public.course_verification_requirements(course_version_id,requirement_key,title,verification_mode,minimum_questions,minimum_options_per_question,passing_score_pct,required,completion_mode,metadata)
  VALUES(v_cv,'final_verification','Verifica aggiornamento: prova pratica e colloquio','practical_and_interview',null,null,null,true,'external','{"regulatory_basis":"ASR 17/04/2025","verification_path_selection_required":false}'::jsonb)
  ON CONFLICT(course_version_id,requirement_key) DO UPDATE SET title=excluded.title,verification_mode=excluded.verification_mode,minimum_questions=null,minimum_options_per_question=null,passing_score_pct=null,required=true,completion_mode=excluded.completion_mode,metadata=excluded.metadata,updated_at=now();
END $do$;
